__global__ void matmul_kernel_tiled(const float* A, const float* B, float* C, int N) {
    // Tile size, chosen for optimal performance on many GPUs.
    // A common value is 16, but 32 can also be effective.
    // Let's start with 32 for potentially higher occupancy if registers allow.
    const int TILE_SIZE = 32;

    // Block index in X and Y directions
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread index within the block
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Calculate the row and column of the C matrix element that this thread is responsible for
    int row = blockRow * TILE_SIZE + threadRow;
    int col = blockCol * TILE_SIZE + threadCol;

    // Shared memory for tiles of A and B
    // __shared__ keyword declares variables that reside in shared memory
    __shared__ float sh_A[TILE_SIZE][TILE_SIZE];
    __shared__ float sh_B[TILE_SIZE][TILE_SIZE];

    float sum = 0.0f;

    // Iterate over the tiles
    // numTiles represents how many 'TILE_SIZE x TILE_SIZE' blocks fit into N
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < numTiles; ++t) {
        // Load tiles from global memory to shared memory
        // Each thread loads one element of the tile

        // Calculate global memory index for A and B elements to be loaded into shared memory
        // Element in A to load: A[row][t * TILE_SIZE + threadCol]
        // Element in B to load: B[t * TILE_SIZE + threadRow][col]

        int A_global_idx = row * N + (t * TILE_SIZE + threadCol);
        int B_global_idx = (t * TILE_SIZE + threadRow) * N + col;

        // Check bounds before loading, important for partial tiles at the edges of the matrix
        if (row < N && (t * TILE_SIZE + threadCol) < N) {
            sh_A[threadRow][threadCol] = A[A_global_idx];
        } else {
            sh_A[threadRow][threadCol] = 0.0f; // Pad with zero if out of bounds
